import { chromium } from 'playwright';

export const BASE = 'http://localhost:3021';
export const EMAIL = 'admin@nxeon.local';
export const PASS = 'iCwEt7PDdo0ne3YM';

export async function loginContext(browser, { width = 1600, height = 1000, theme = null } = {}) {
  const ctx = await browser.newContext({ viewport: { width, height }, deviceScaleFactor: 1 });
  if (theme) {
    await ctx.addInitScript((t) => {
      try { localStorage.setItem('nx-theme', t); } catch {}
    }, theme);
  }
  const page = await ctx.newPage();
  const logs = [];
  page.on('console', (msg) => {
    if (['error', 'warning'].includes(msg.type())) {
      logs.push(`[${msg.type()}] ${msg.text()}`);
    }
  });
  page.on('pageerror', (err) => logs.push(`[pageerror] ${err.message}`));
  page.on('requestfailed', (req) => {
    // ignore analytics/beacon noise but capture others
    logs.push(`[requestfailed] ${req.method()} ${req.url()} - ${req.failure()?.errorText}`);
  });

  await page.goto(`${BASE}/login`, { waitUntil: 'domcontentloaded' });
  // dismiss cookie banner if present
  const gotIt = page.locator('button:has-text("Got it")');
  if (await gotIt.isVisible().catch(() => false)) {
    await gotIt.click().catch(() => {});
  }
  await page.fill('input[type="email"], input[name="email"]', EMAIL);
  await page.fill('input[type="password"], input[name="password"]', PASS);
  await Promise.all([
    page.waitForURL((u) => !u.pathname.includes('/login'), { timeout: 45000 }).catch(() => {}),
    page.click('button.btn-primary'),
  ]);
  await page.waitForTimeout(1500);
  page._logs = logs;
  return { ctx, page, logs };
}

export { chromium };

import { chromium, loginContext, BASE } from './lib.mjs';

async function main() {
  const browser = await chromium.launch();
  const { page, logs } = await loginContext(browser, { width: 1600, height: 1100 });

  console.log('URL after login:', page.url());
  await page.goto(`${BASE}/dashboard`, { waitUntil: 'networkidle' });
  await page.waitForTimeout(2000);
  await page.screenshot({ path: '/opt/nxeon-v2/.audit-tmp/dash-dark-1600.png', fullPage: true });

  console.log('--- Console logs after dashboard load (dark, 1600px) ---');
  console.log(logs.join('\n') || '(none)');

  // Grab stats tiles text
  const bodyText = await page.locator('body').innerText();
  console.log('--- Page text snapshot (first 3000 chars) ---');
  console.log(bodyText.slice(0, 3000));

  await browser.close();
}

main().catch(e => { console.error(e); process.exit(1); });

import { chromium, loginContext, BASE } from './lib.mjs';

async function main() {
  const browser = await chromium.launch();
  const { page, logs } = await loginContext(browser, { width: 1600, height: 1100 });
  await page.goto(`${BASE}/dashboard`, { waitUntil: 'networkidle' });
  await page.waitForTimeout(1500);

  const gotIt = page.locator('button:has-text("Got it")');
  if (await gotIt.isVisible().catch(() => false)) await gotIt.click().catch(() => {});
  await page.waitForTimeout(500);

  // Find the promo carousel region - look for dots
  const dotsContainer = page.locator('.absolute, div').filter({ hasText: '' });
  // Try to find dot buttons near "FREE FOREVER" card
  const carousel = page.locator('div', { hasText: 'Your first server' }).last();

  // Let's just find all small round buttons in the right rail area (x > 1180)
  const allButtons = await page.locator('button').all();
  console.log('Total buttons on page:', allButtons.length);

  // Look for dot indicators - typically small buttons with no text, in a row
  // Let's screenshot the carousel region first
  const promoCard = page.locator('text=Your first server').first();
  await promoCard.scrollIntoViewIfNeeded().catch(() => {});
  await page.screenshot({ path: '/opt/nxeon-v2/.audit-tmp/carousel-slide1.png', clip: { x: 1180, y: 340, width: 420, height: 460 } });

  // Try clicking dots - guess they are buttons with aria-label like "Go to slide"
  const dotButtons = page.locator('button[aria-label*="slide" i], button[aria-label*="Go to" i]');
  const dotCount = await dotButtons.count();
  console.log('Dot buttons found via aria-label:', dotCount);

  if (dotCount === 0) {
    // dump HTML around the carousel for inspection
    const html = await page.locator('body').innerHTML();
    require('fs').writeFileSync('/opt/nxeon-v2/.audit-tmp/dashboard-body.html', html);
    console.log('Saved full body HTML for inspection.');
  } else {
    for (let i = 0; i < dotCount; i++) {
      await dotButtons.nth(i).click();
      await page.waitForTimeout(600);
      await page.screenshot({ path: `/opt/nxeon-v2/.audit-tmp/carousel-dot-${i}.png`, clip: { x: 1180, y: 340, width: 420, height: 460 } });
    }
  }

  console.log('--- logs ---');
  console.log(logs.filter(l => !l.includes('_rsc=')).join('\n') || '(none)');

  await browser.close();
}

main().catch(e => { console.error(e); process.exit(1); });

