93	const HOLD = 3600;
94	/** Horizontal drag past this many px counts as a swipe, not a tap/tilt. */
95	const SWIPE_PX = 40;
96	
97	export function PromoCarousel({ items = PROMOS }: { items?: Promo[] }) {
98	  const [n, setN] = useState(0);
99	  const [hold, setHold] = useState(false);
100	  const still = useRef(false);
101	
102	  const go = (dir: 1 | -1) => setN((v) => (v + dir + items.length) % items.length);
103	
104	  useEffect(() => { still.current = window.matchMedia("(prefers-reduced-motion: reduce)").matches; }, []);
105	  useEffect(() => {
106	    if (hold || still.current) return;
107	    const t = setTimeout(() => go(1), HOLD);
108	    return () => clearTimeout(t);
109	    // eslint-disable-next-line react-hooks/exhaustive-deps
110	  }, [n, hold, items.length]);
111	
112	  const p = items[n];
113	
114	  /* Swipe: tracked on the pointer that started the drag, not by re-deriving
115	     hover/tilt state — a swipe should work on touch, where there is no hover
116	     to hold the rotation still in the first place, so it pauses it itself
117	     for the duration of the drag. */
118	  const swipe = useRef<{ x: number; id: number } | null>(null);
119	  const onSwipeStart = (e: React.PointerEvent) => {
120	    swipe.current = { x: e.clientX, id: e.pointerId };
121	    setHold(true);
122	  };
123	  const onSwipeEnd = (e: React.PointerEvent) => {
124	    const s = swipe.current;
125	    swipe.current = null;
126	    if (!s || s.id !== e.pointerId) { setHold(false); return; }
127	    const dx = e.clientX - s.x;
128	    if (Math.abs(dx) >= SWIPE_PX) go(dx < 0 ? 1 : -1);
129	    onLeave();
130	  };
131	
132	  /* the tilt is written straight to the node — running it through state would
133	     re-render the whole card on every pointer move */
134	  const tilt = useRef<HTMLDivElement>(null);
135	  const raf = useRef(0);
136	  const onMove = (e: React.MouseEvent) => {
137	    if (still.current) return;
138	    const el = tilt.current; if (!el) return;
139	    const r = el.getBoundingClientRect();
140	    const x = (e.clientX - r.left) / r.width - 0.5;
141	    const y = (e.clientY - r.top) / r.height - 0.5;
142	    cancelAnimationFrame(raf.current);
143	    raf.current = requestAnimationFrame(() => {
144	      el.style.transition = "none";
145	      el.style.transform =
146	        `rotateX(${(-y * 9).toFixed(2)}deg) rotateY(${(x * 11).toFixed(2)}deg) translateY(-6px) scale(1.012)`;
147	      /* the specular slides opposite the tilt, the way a real gloss would */
148	      el.style.setProperty("--sx", `${(50 - x * 55).toFixed(1)}%`);
149	    });
150	  };
151	  const onLeave = () => {
152	    setHold(false);
153	    const el = tilt.current; if (!el) return;
154	    el.style.transition = "";
155	    el.style.transform = "";
156	    el.style.removeProperty("--sx");
157	  };
158	
159	  return (
160	    <div className="lg-stage flex min-h-0 flex-1 flex-col touch-pan-y"
161	         onMouseMove={onMove} onMouseEnter={() => setHold(true)} onMouseLeave={onLeave}
162	         onFocusCapture={() => setHold(true)} onBlurCapture={() => setHold(false)}
163	         onPointerDown={onSwipeStart} onPointerUp={onSwipeEnd} onPointerCancel={onLeave}>
164	      <span aria-hidden className="lg-floor"
165	            style={{ background: `radial-gradient(circle, rgba(${p.tint},0.75), rgba(${p.tint},0) 70%)` }} />
166	      <div ref={tilt} className="lg-tilt relative min-h-0 flex-1">
167	      <span aria-hidden className="lgc-glow" />
168	      {/* nx-dark-island: every colour inside this card is tuned against its
169	          OWN artwork + scrim (see the file comment), never the page — light
170	          mode's generic .glass fix would otherwise turn the sheet bright
171	          white while the title/body text stayed the same pale, dark-tuned
172	          colour, which is how it went unreadable. Scoped to the card face
173	          itself, not the outer padded stage, so it doesn't paint an opaque
174	          dark box into the stage's own (transparent, page-coloured) padding. */}
175	      <section className="nx-dark-island lgc lg-lift relative h-full" aria-roledescription="carousel">
176	      <div className="lgc-in h-full">
177	        {/* ── artwork, held well back ───────────────────────────────────── */}
178	        {items.map((q, i) => (
179	          <img key={q.key} src={q.img} alt="" aria-hidden draggable={false}
180	               className={"absolute inset-0 h-full w-full object-cover transition-opacity duration-[900ms] ease-out " +
181	                          (i === n ? "opacity-100" : "opacity-0")} />
182	        ))}
183	        {/* 75% over the art, easing back behind the sheet — glass with nothing
184	            but black behind it just reads as a grey panel */}
185	        <span aria-hidden className="absolute inset-0"
186	              style={{ background: "linear-gradient(180deg, rgba(0,3,12,0.54) 0%, rgba(0,3,12,0.50) 38%, rgba(0,3,12,0.58) 62%, rgba(0,3,12,0.66) 100%)" }} />
187	        <span aria-hidden className="absolute inset-0 transition-[background] duration-700"
188	              style={{ background: `radial-gradient(110% 62% at 68% 6%, rgba(${p.tint},0.20), transparent 62%)` }} />
189	
190	        {/* ── top bar ──────────────────────────────────────────────────── */}
191	        <div className="absolute inset-x-[18px] top-[18px] z-10 flex items-center justify-between gap-3">
192	          <span key={p.key} className="nx-rise flex h-[25px] items-center gap-[7px] rounded-full
193	                                       border border-[rgba(140,205,255,0.34)] bg-[rgba(8,22,52,0.42)] px-2.5
194	                                       text-[9px] font-bold uppercase tracking-[0.19em] text-[#d6ecff]
195	                                       backdrop-blur-[10px]">
196	            <span style={{ color: `rgb(${p.tint})` }}><G d={P.spark} size={10} fill /></span>
197	            {p.eyebrow}
198	          </span>
