import { chromium, loginContext, BASE } from './lib.mjs';

const EYEBROWS = ["Nxeon Matrix", "Free forever", "Referral Program", "Home region", "Community", "Nxeon"];

async function main() {
  const browser = await chromium.launch();
  const { page, logs } = await loginContext(browser, { width: 1600, height: 1100 });
  await page.goto(`${BASE}/dashboard`, { waitUntil: 'networkidle' });
  await page.waitForTimeout(1500);
  const gotIt = page.locator('button:has-text("Got it")');
  if (await gotIt.isVisible().catch(() => false)) await gotIt.click().catch(() => {});
  await page.waitForTimeout(500);

  for (let i = 0; i < EYEBROWS.length; i++) {
    const dot = page.locator(`button[aria-label="${EYEBROWS[i]}"]`);
    const count = await dot.count();
    if (count === 0) {
      console.log(`Slide ${i} (${EYEBROWS[i]}): DOT BUTTON NOT FOUND`);
      continue;
    }
    await dot.first().click();
    await page.waitForTimeout(900);
    await page.screenshot({ path: `/opt/nxeon-v2/.audit-tmp/carousel-${i}-${EYEBROWS[i].replace(/\s+/g,'_')}.png`, clip: { x: 1180, y: 340, width: 420, height: 460 } });

    // find the CTA button/link inside the card (btn btn-xs)
    const cta = page.locator('a.btn-xs, a.btn.btn-xs, button.btn-xs, button.btn.btn-xs').last();
    const ctaCount = await cta.count();
    if (ctaCount === 0) {
      console.log(`Slide ${i} (${EYEBROWS[i]}): NO CTA BUTTON (may be by design for brand slide)`);
      continue;
    }
    const ctaText = await cta.innerText().catch(() => '?');
    const tag = await cta.evaluate(el => el.tagName).catch(() => '?');
    const href = await cta.getAttribute('href').catch(() => null);
    const target = await cta.getAttribute('target').catch(() => null);
    console.log(`Slide ${i} (${EYEBROWS[i]}): CTA="${ctaText}" tag=${tag} href=${href} target=${target}`);
  }

  console.log('--- logs ---');
  console.log(logs.filter(l => !l.includes('_rsc=')).join('\n') || '(none)');

  await browser.close();
}

main().catch(e => { console.error(e); process.exit(1); });

import { chromium, loginContext, BASE } from './lib.mjs';

const SLIDES = [
  { eyebrow: "Nxeon Matrix", expectPath: "/dashboard/build" },
  { eyebrow: "Free forever", expectPath: "/dashboard/services" },
  { eyebrow: "Referral Program", expectPath: "/dashboard/refer" },
  { eyebrow: "Home region", expectPath: "/dashboard/deploy" },
];

async function main() {
  const browser = await chromium.launch();
  const { page, logs } = await loginContext(browser, { width: 1600, height: 1100 });

  for (const s of SLIDES) {
    await page.goto(`${BASE}/dashboard`, { waitUntil: 'networkidle' });
    await page.waitForTimeout(1200);
    const gotIt = page.locator('button:has-text("Got it")');
    if (await gotIt.isVisible().catch(() => false)) await gotIt.click().catch(() => {});
    const dot = page.locator(`button[aria-label="${s.eyebrow}"]`).first();
    await dot.click();
    await page.waitForTimeout(700);
    const cta = page.locator('a.btn-xs, a.btn.btn-xs').last();
    await cta.click();
    await page.waitForTimeout(1500);
    const url = page.url();
    const ok = url.includes(s.expectPath);
    console.log(`${s.eyebrow}: navigated to ${url} -- ${ok ? 'OK' : 'MISMATCH expected ' + s.expectPath}`);
  }

  // discord (external) - just check target
  await page.goto(`${BASE}/dashboard`, { waitUntil: 'networkidle' });
  await page.waitForTimeout(1000);
  const dot = page.locator(`button[aria-label="Community"]`).first();
  await dot.click();
  await page.waitForTimeout(700);
  const cta = page.locator('a.btn-xs, a.btn.btn-xs').last();
  const [popup] = await Promise.all([
    page.context().waitForEvent('page', { timeout: 5000 }).catch(() => null),
    cta.click(),
  ]);
  if (popup) {
