  console.log('CTA bounding box:', box);

  const info = await page.evaluate(({x, y}) => {
    const el = document.elementFromPoint(x, y);
    function describe(e) {
      if (!e) return null;
      return { tag: e.tagName, cls: e.className, href: e.getAttribute && e.getAttribute('href') };
    }
    const chain = [];
    let cur = el;
    for (let i = 0; i < 6 && cur; i++) { chain.push(describe(cur)); cur = cur.parentElement; }
    return chain;
  }, { x: box.x + box.width / 2, y: box.y + box.height / 2 });
  console.log('Element chain at CTA center:', JSON.stringify(info, null, 2));

  await browser.close();
}

