async function main() {
  const browser = await chromium.launch();
  const { page } = await loginContext(browser, { width: 1600, height: 1100 });
  await page.goto(`${BASE}/dashboard`, { waitUntil: 'networkidle' });
  await page.waitForTimeout(1200);
  const gotIt = page.locator('button:has-text("Got it")');
  if (await gotIt.isVisible().catch(() => false)) await gotIt.click().catch(() => {});
  await page.waitForTimeout(500);

  // Select the "Nxeon Matrix" slide explicitly.
  const dot = page.locator(`button[aria-label="Nxeon Matrix"]`).first();
  await dot.click();
  await page.waitForTimeout(500);

  const target = page.locator('a.btn-xs, a.btn.btn-xs').last();
  const boxBefore = await target.boundingBox();
  console.log('CTA box BEFORE any hover:', boxBefore);

  // Simulate a real user: move mouse onto the card first (triggers tilt), then to the button.
  await page.mouse.move(boxBefore.x - 100, boxBefore.y - 100);
  await page.waitForTimeout(150);
  await page.mouse.move(boxBefore.x + boxBefore.width / 2, boxBefore.y + boxBefore.height / 2, { steps: 10 });
  await page.waitForTimeout(200);

  const boxAfter = await target.boundingBox();
  console.log('CTA box AFTER hover/tilt:', boxAfter);
  console.log('Delta x:', boxAfter.x - boxBefore.x, 'Delta y:', boxAfter.y - boxBefore.y);

  // Check what's actually at the ORIGINAL (pre-tilt) coordinates now.
  const cx = boxBefore.x + boxBefore.width / 2;
  const cy = boxBefore.y + boxBefore.height / 2;
  const elAtOriginal = await page.evaluate(({x,y}) => {
    const e = document.elementFromPoint(x,y);
    return e ? { tag: e.tagName, cls: e.className, href: e.getAttribute && e.getAttribute('href') } : null;
  }, { x: cx, y: cy });
  console.log('Element at ORIGINAL pre-tilt center point, after tilt applied:', elAtOriginal);

  // Now actually click via mouse down/up at that same original coordinate (mimics a real click after hovering).
  await page.mouse.down();
  await page.mouse.up();
  await page.waitForTimeout(1500);
  console.log('URL after click-at-original-point:', page.url());

  await browser.close();
}

main().catch(e => { console.error(e); process.exit(1); });

