import { chromium, loginContext, BASE } from './lib.mjs';

async function main() {
  const browser = await chromium.launch();
  const { page } = await loginContext(browser, { width: 1600, height: 1100 });
  await page.goto(`${BASE}/dashboard`, { waitUntil: 'networkidle' });
  await page.waitForTimeout(1000);
  const gotIt = page.locator('button:has-text("Got it")');
  if (await gotIt.isVisible().catch(() => false)) await gotIt.click().catch(() => {});
  await page.waitForTimeout(1000);

  const dot = page.locator(`button[aria-label="Community"]`).first();
  await dot.click();
  await page.waitForTimeout(1500);

  const target = page.locator('a.btn-xs, a.btn.btn-xs').last();
  const box = await target.boundingBox();
  console.log('CTA box:', box);

  const cx = box.x + box.width / 2;
  const cy = box.y + box.height / 2;
  const info = await page.evaluate(({x,y}) => {
    const els = document.elementsFromPoint(x,y);
    return els.slice(0,8).map(e => ({ tag: e.tagName, id: e.id, cls: (e.className||'').toString().slice(0,80), z: getComputedStyle(e).zIndex, pos: getComputedStyle(e).position }));
  }, { x: cx, y: cy });
  console.log('Stack of elements at CTA center (topmost first):');
  console.log(JSON.stringify(info, null, 2));

  // also check top-right corner of the CTA (closest to floating chat widget)
  const cx2 = box.x + box.width - 5;
  const cy2 = box.y + box.height / 2;
  const info2 = await page.evaluate(({x,y}) => {
    const els = document.elementsFromPoint(x,y);
    return els.slice(0,5).map(e => ({ tag: e.tagName, id: e.id, cls: (e.className||'').toString().slice(0,80) }));
  }, { x: cx2, y: cy2 });
  console.log('Stack at right-edge of CTA:', JSON.stringify(info2, null, 2));

  await page.screenshot({ path: '/opt/nxeon-v2/.audit-tmp/overlap-check.png', clip: { x: 1150, y: 950, width: 450, height: 150 } });

  await browser.close();
}

main().catch(e => { console.error(e); process.exit(1); });

