import { chromium, loginContext, BASE } from './lib.mjs';

async function main() {
  const browser = await chromium.launch();
  const { page } = await loginContext(browser, { width: 1600, height: 1100 });
  await page.goto(`${BASE}/dashboard`, { waitUntil: 'networkidle' });
  await page.waitForTimeout(1000);
  const gotIt = page.locator('button:has-text("Got it")');
  if (await gotIt.isVisible().catch(() => false)) await gotIt.click().catch(() => {});
  await page.waitForTimeout(1000);

  const dot = page.locator(`button[aria-label="Community"]`).first();
  await dot.click();
  await page.waitForTimeout(1500);

  await page.exposeFunction('reportClick', (data) => console.log('CLICK EVENT:', JSON.stringify(data)));
  await page.evaluate(() => {
    const a = document.querySelectorAll('a.btn-xs, a.btn.btn-xs');
    const el = a[a.length - 1];
    window.__el = el;
    ['pointerdown','pointerup','mousedown','mouseup','click','auxclick'].forEach(evt => {
      el.addEventListener(evt, (e) => {
        window.reportClick({ type: evt, defaultPrevented: e.defaultPrevented, button: e.button, target: e.target.tagName });
      }, true);
    });
    // also listen at document level for click to see if it bubbles / gets stopped
    document.addEventListener('click', (e) => {
      window.reportClick({ type: 'document-click', defaultPrevented: e.defaultPrevented, path: e.composedPath().slice(0,3).map(x=>x.tagName||x.nodeName) });
    }, true);
  });

  const target = page.locator('a.btn-xs, a.btn.btn-xs').last();
  await target.click();
  await page.waitForTimeout(2000);
  console.log('Final URL:', page.url());

  await browser.close();
}

main().catch(e => { console.error(e); process.exit(1); });

import { chromium, loginContext, BASE } from './lib.mjs';

async function main() {
  const browser = await chromium.launch();
  const { page } = await loginContext(browser, { width: 1600, height: 1100 });
  await page.goto(`${BASE}/dashboard`, { waitUntil: 'networkidle' });
  await page.waitForTimeout(1000);
  const gotIt = page.locator('button:has-text("Got it")');
  if (await gotIt.isVisible().catch(() => false)) await gotIt.click().catch(() => {});
  await page.waitForTimeout(500);

  // Hover over the card FIRST (engages `hold`, freezing autoplay) before doing anything else.
  const cardArea = page.locator('section.lgc').first();
  const cardBox = await cardArea.boundingBox();
  await page.mouse.move(cardBox.x + cardBox.width/2, cardBox.y + cardBox.height/2);
  await page.waitForTimeout(300);

  const dot = page.locator(`button[aria-label="Community"]`).first();
  await dot.click(); // still within the hovered region, hold stays true
  await page.waitForTimeout(600);

  const target = page.locator('a.btn-xs, a.btn.btn-xs').last();
  const href = await target.getAttribute('href');
  console.log('CTA href (should be discord):', href);

  const box = await target.boundingBox();
  await page.mouse.move(box.x + box.width/2, box.y + box.height/2, { steps: 5 });
  await page.waitForTimeout(150);

  const [popup] = await Promise.all([
    page.context().waitForEvent('page', { timeout: 5000 }).catch(() => null),
    page.mouse.down(),
  ]);
  await page.mouse.up();
  await page.waitForTimeout(1500);

  if (popup) {
    await popup.waitForLoadState('domcontentloaded').catch(() => {});
    console.log('SUCCESS: new tab opened ->', popup.url());
  } else {
    console.log('FAILURE: no new tab. current url:', page.url());
  }

  await browser.close();
}

main().catch(e => { console.error(e); process.exit(1); });

