import { chromium, loginContext, BASE } from './lib.mjs';

async function main() {
  const browser = await chromium.launch();
  const { page } = await loginContext(browser, { width: 1600, height: 1100 });
  await page.goto(`${BASE}/dashboard`, { waitUntil: 'networkidle' });
  await page.waitForTimeout(1000);
  const gotIt = page.locator('button:has-text("Got it")');
  if (await gotIt.isVisible().catch(() => false)) await gotIt.click().catch(() => {});
  await page.waitForTimeout(500);

  const dot = page.locator(`button[aria-label="Community"]`).first();
  await dot.click();
  await page.waitForTimeout(600);

  const target = page.locator('a.btn-xs, a.btn.btn-xs').last();
  const box = await target.boundingBox();
  console.log('CTA box:', box);

  // Natural mouse path: approach from outside the card, ending exactly on the button, in one smooth motion.
  await page.mouse.move(box.x - 300, box.y - 300);
  await page.mouse.move(box.x + box.width/2, box.y + box.height/2, { steps: 25 });
  await page.waitForTimeout(250);

  // Re-check element under cursor at THIS final settled position.
  const cx = box.x + box.width/2, cy = box.y + box.height/2;
  const hit = await page.evaluate(({x,y}) => {
    const e = document.elementFromPoint(x,y);
    return e ? { tag: e.tagName, cls: (e.className||'').toString().slice(0,60), href: e.getAttribute && e.getAttribute('href') } : null;
  }, {x: cx, y: cy});
  console.log('Element under cursor at settled hover position:', hit);

  const [popup] = await Promise.all([
    page.context().waitForEvent('page', { timeout: 5000 }).catch(() => null),
    page.mouse.down(),
  ]);
  await page.mouse.up();
  await page.waitForTimeout(1200);

  if (popup) {
    console.log('SUCCESS: new tab ->', popup.url());
  } else {
    console.log('FAILURE: no popup. url:', page.url());
  }

  await browser.close();
}

main().catch(e => { console.error(e); process.exit(1); });

