import { chromium, loginContext, BASE } from './lib.mjs';

async function measure(browser, width) {
  const { page } = await loginContext(browser, { width, height: 800 });
  await page.goto(`${BASE}/dashboard/services`, { waitUntil: 'networkidle' });
  await page.waitForTimeout(1000);
  const gotIt = page.locator('button:has-text("Got it")');
  if (await gotIt.isVisible().catch(() => false)) await gotIt.click().catch(() => {});
  await page.waitForTimeout(400);

  const info = await page.evaluate(() => {
    const header = document.querySelector('header');
    const tagline = Array.from(document.querySelectorAll('span')).find(s => s.textContent === 'SAME INFRASTRUCTURE.');
    const rackWrap = tagline ? tagline.parentElement.previousElementSibling : null; // the rack <span> is previous sibling of tagline span container
    const hb = header.getBoundingClientRect();
    const tb = tagline ? tagline.getBoundingClientRect() : null;
    const rb = rackWrap ? rackWrap.getBoundingClientRect() : null;
    return {
      headerRect: { x: hb.x, right: hb.right, width: hb.width },
      taglineRect: tb ? { x: tb.x, right: tb.right, width: tb.width } : null,
      rackRect: rb ? { x: rb.x, right: rb.right, width: rb.width } : null,
    };
  });
  console.log(`viewport ${width}:`, JSON.stringify(info));
  await page.context().close();
}

async function main() {
  const browser = await chromium.launch();
  for (const w of [1440, 1600, 1728, 1800, 1920, 2000, 2200]) {
    await measure(browser, w);
  }
  await browser.close();
}

main().catch(e => { console.error(e); process.exit(1); });

