import { chromium, loginContext, BASE } from './lib.mjs';

const PAGES = [
  { url: '/dashboard/servers/cmtvcf5sj000asb634qakwex3', label: 'gameserver-myserver' },
  { url: '/dashboard/servers/cmtot7pos0005hlf08v1zwbg1', label: 'vps-dbprimary' },
  { url: '/dashboard/servers/cmtot7ppn000bhlf06ssy6lsm', label: 'gameserver-mcsurvival' },
  { url: '/dashboard/hosting/sandbox-host-1', label: 'hosting-provcheck' },
  { url: '/dashboard/hosting/cmtpgbv6g000phldwv2r9vxbc', label: 'hosting-nxadmin' },
  { url: '/dashboard/email', label: 'business-email' },
];

async function main() {
  const browser = await chromium.launch();
  for (const p of PAGES) {
    const { page, logs } = await loginContext(browser, { width: 1600, height: 1200 });
