1	import { NextRequest, NextResponse } from "next/server";
2	import { db } from "@/lib/db";
3	import { currentUser } from "@/lib/auth";
4	import { getGuestDiskUsage, pve, node as defaultNode, pveFor } from "@/lib/proxmox";
5	import { effectiveDiskGB, baseDiskGBFor } from "@/lib/extra-disk";
6	import { NO_STORE_HEADERS } from "@/app/api/_lib/no-store";
7	
8	export const dynamic = "force-dynamic";
9	
10	type Pt = { time: number; disk: number | null; maxdisk: number | null };
11	
12	// Chart timeframe → lookback window (ms). Matches DiskUsageChart's 24h/7d/30d.
13	const WINDOW_MS: Record<string, number> = {
14	  day: 24 * 60 * 60_000,
15	  week: 7 * 24 * 60 * 60_000,
16	  month: 30 * 24 * 60 * 60_000,
17	};
18	
19	/**
20	 * Real in-guest disk usage for a server the current user owns.
21	 *
22	 * Data comes from ServerDiskSample (collected by the worker via the QEMU guest
23	 * agent, since Proxmox RRD reports disk=0 for QEMU VMs) for the requested
24	 * window, plus a fresh live get-fsinfo reading appended as the current point.
25	 * Falls back to the latest stored sample when the live call isn't ready, and to
26	 * an empty series (chart shows the "not reporting" note) only when neither the
27	 * agent nor any sample yields anything.
28	 */
29	export async function GET(req: NextRequest, ctx: { params: Promise<{ id: string }> }) {
30	  const { id } = await ctx.params;
31	  const user = await currentUser();
32	  if (!user) {
33	    return NextResponse.json({ error: "unauthorized" }, { status: 401, headers: NO_STORE_HEADERS });
34	  }
35	
36	  const tf = req.nextUrl.searchParams.get("tf") ?? "day";
37	
38	  const server = await db.server.findUnique({
39	    where: { id },
40	    include: { node: true, plan: true, gamePlan: true },
41	  });
42	  if (!server || (server.userId !== user.id && user.role !== "ADMIN") || !server.vmid) {
43	    return NextResponse.json({ error: "not found" }, { status: 404, headers: NO_STORE_HEADERS });
44	  }
45	
46	  // Effective disk (plan + purchased extra) — a server that bought extra storage
47	  // must not be charted against its plan's smaller allowance. For a game
48	  // server this is the game plan's disk, not the (larger) base VPS plan it
49	  // rides on — see lib/extra-disk.ts's baseDiskGBFor.
50	  const planTotalBytes = effectiveDiskGB(baseDiskGBFor(server), server.extraDiskGB) * 1024 ** 3;
51	  const since = new Date(Date.now() - (WINDOW_MS[tf] ?? WINDOW_MS.day));
52	
53	  // 1. Stored history for the window.
54	  let samples: { ts: Date; usedBytes: bigint; totalBytes: bigint }[] = [];
55	  try {
56	    samples = await db.serverDiskSample.findMany({
57	      where: { serverId: id, ts: { gte: since } },
58	      orderBy: { ts: "asc" },
59	      select: { ts: true, usedBytes: true, totalBytes: true },
60	    });
61	  } catch {
62	    samples = [];
63	  }
64	
65	  const data: Pt[] = samples.map((s) => ({
66	    time: Math.floor(s.ts.getTime() / 1000),
67	    disk: Number(s.usedBytes),
68	    maxdisk: Number(s.totalBytes),
69	  }));
70	
71	  // 2. Fresh live reading for the current point (best-effort).
72	  let current: { usedBytes: number; totalBytes: number } | null = null;
73	  try {
74	    const client = server.node
75	      ? pveFor({
76	          apiUrl: server.node.apiUrl,
77	          pveNode: server.node.pveNode,
78	          tokenId: server.node.tokenId,
79	          tokenSecret: server.node.tokenSecret,
80	        })
81	      : pve;
82	    const pnode = server.node?.pveNode ?? defaultNode;
83	    current = await getGuestDiskUsage(client, pnode, server.vmid, planTotalBytes);
84	  } catch {
85	    current = null;
86	  }
87	
88	  // Fall back to the newest stored sample when the live call isn't ready.
89	  if (!current && samples.length > 0) {
90	    const last = samples[samples.length - 1];
91	    current = { usedBytes: Number(last.usedBytes), totalBytes: Number(last.totalBytes) };
92	  }
93	
94	  // Append the current reading so the chart always shows the freshest value
95	  // (and isn't empty when there are no samples yet but the agent responds).
96	  if (current) {
97	    data.push({
98	      time: Math.floor(Date.now() / 1000),
99	      disk: current.usedBytes,
100	      maxdisk: current.totalBytes,
101	    });
102	  }
103	
104	  return NextResponse.json({ data, planTotalBytes }, { headers: NO_STORE_HEADERS });
105	}
