import { chromium, loginContext, BASE } from './lib.mjs';

async function main() {
  const browser = await chromium.launch();

  // Light mode check on a VPS detail page
  const { page, logs } = await loginContext(browser, { width: 1600, height: 1100, theme: 'light' });
  await page.goto(`${BASE}/dashboard/servers/cmtot7pos0005hlf08v1zwbg1`, { waitUntil: 'domcontentloaded', timeout: 20000 });
  await page.waitForTimeout(3000);
  const gotIt = page.locator('button:has-text("Got it")');
  if (await gotIt.isVisible().catch(() => false)) await gotIt.click().catch(() => {});
