  await page.screenshot({ path: '/opt/nxeon-v2/.audit-tmp/vps-light-mode.png', fullPage: true });
  console.log('--- VPS detail, light mode, logs ---');
  console.log(logs.filter(l => !l.includes('_rsc=') && !l.includes('/api/metrics') && !l.includes('/disk?')).join('\n') || '(none other than known metrics 404s)');

  // Click through a couple of tabs
  for (const tab of ['Console', 'Backups', 'Networking', 'Settings']) {
    const t = page.locator(`button:has-text("${tab}")`).first();
    if (await t.count() > 0) {
      await t.click();
