      await page.screenshot({ path: `/opt/nxeon-v2/.audit-tmp/vps-tab-${tab}.png` });
    }
  }
  console.log('--- after tab clicks, new logs ---');
  console.log(logs.filter(l => !l.includes('_rsc=') && !l.includes('/api/metrics') && !l.includes('/disk?')).join('\n') || '(none)');

  await page.context().close();
  await browser.close();
}

main().catch(e => { console.error(e); process.exit(1); });

import { chromium, loginContext, BASE } from './lib.mjs';

async function shot(browser, theme, url, label) {
  const { page } = await loginContext(browser, { width: 1600, height: 900, theme });
  await page.goto(`${BASE}${url}`, { waitUntil: 'domcontentloaded', timeout: 20000 });
  await page.waitForTimeout(2500);
  const gotIt = page.locator('button:has-text("Got it")');
  if (await gotIt.isVisible().catch(() => false)) await gotIt.click().catch(() => {});
  await page.waitForTimeout(500);
  await page.screenshot({ path: `/opt/nxeon-v2/.audit-tmp/theme-${label}.png` });
  await page.context().close();
}

async function main() {
  const browser = await chromium.launch();
  await shot(browser, null, '/dashboard/servers/cmtot7pos0005hlf08v1zwbg1', 'vps-dark');
  await shot(browser, 'light', '/dashboard/servers/cmtot7pos0005hlf08v1zwbg1', 'vps-light');
  await shot(browser, 'light', '/dashboard/hosting/sandbox-host-1', 'hosting-light');
  await shot(browser, 'light', '/dashboard/email', 'email-light');
  await shot(browser, 'light', '/dashboard/servers/cmtvcf5sj000asb634qakwex3', 'gameserver-light');
